def infer_cycle(g):
    # Use the longest intact horizontal run in the regular patterned interior.
    best=[]; anchor=None
    for r in range(6,len(g)):
        c=6
        while c<len(g[r]):
            if g[r][c]==0:
                c+=1; continue
            s=c
            while c<len(g[r]) and g[r][c]!=0: c+=1
            if c-s>len(best): best=g[r][s:c]; anchor=(r,s)
    if not best: raise ValueError('no visible pattern run')
    n=len(best)
    p=next((p for p in range(1,n//2+1) if all(best[i]==best[i%p] for i in range(n))), None)
    if p is None: raise ValueError(('period not detected',best))
    return best[:p],anchor

def transform(grid):
    g=[row[:] for row in grid]
    cyc,(r0,c0)=infer_cycle(g)
    p=len(cyc)
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c]!=0: continue
            if r<2 or c<2:
                g[r][c]=1
            elif r==2 or c==2:
                g[r][c]=4
            else:
                g[r][c]=cyc[(r-r0+c-c0)%p]
    return g

